// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint64 tsAdvance, uint32 blockNum) public {
        vm.assume(actor != address(0));

        uint256 curBlock = block.number;
        uint256 targetBlock = bound(uint256(blockNum), curBlock, curBlock + 1000);
        vm.roll(targetBlock);

        uint256 curTs = block.timestamp;
        uint256 advance = bound(uint256(tsAdvance), 1, 1 days);
        vm.warp(curTs + advance);

        vm.deal(actor, 20 ether);
        vm.deal(address(c), 5 ether);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        if (block.number % 15 != 0) {
            assertTrue(address(c).balance > 0);
        } else {
            assertTrue(address(c).balance == 0 || address(c).balance > 0);
        }
    }
}
